export const CSP_NONCE_META_NAME = 'metalgym88-csp-nonce'

// This is the canonical Pages policy. The tracked _headers copies and the HTML
// meta fallback are regression-tested against it. Mercado Pago's SDK v2
// bootstrap is authorized by a per-response nonce instead of unstable hashes
// for content generated by /devices/widgets.
export const CANONICAL_CSP = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  'upgrade-insecure-requests',
  "script-src 'self' 'sha256-jYHg7tXSuuVUqjy+JeRT8vyG97+Spkw5IFHdQEBbmrw=' 'sha256-Y8gZRRAdU1zK6frCTDDEcEN+fvPKQZLtSHr+o1pW1Og=' 'sha256-GRqTQiLptG6wuhtB52asFIQM5iVu0U4w9MQbYH/xszE=' https://*.paypal.com https://*.paypalobjects.com https://www.googletagmanager.com https://static.cloudflareinsights.com https://sdk.mercadopago.com https://http2.mlstatic.com",
  "style-src 'self' 'unsafe-inline' https://*.paypal.com https://*.paypalobjects.com https://sdk.mercadopago.com https://http2.mlstatic.com",
  "img-src 'self' data: blob: https:",
  "font-src 'self' data: https://http2.mlstatic.com",
  "connect-src 'self' https://api.djlabs.cl https://*.paypal.com https://*.paypalobjects.com https://www.googletagmanager.com https://www.google-analytics.com https://cloudflareinsights.com https://api.mercadopago.com https://api-static.mercadopago.com https://sdk.mercadopago.com https://secure-fields.mercadopago.com https://secure-fields-stg.mercadopago.com https://http2.mlstatic.com",
  "frame-src 'self' https://*.paypal.com https://*.paypalobjects.com https://www.googletagmanager.com https://secure-fields.mercadopago.com https://secure-fields-stg.mercadopago.com https://acs.mercadopago.com https://api.mercadopago.com",
  "child-src 'self' https://*.paypal.com https://*.paypalobjects.com https://secure-fields.mercadopago.com https://secure-fields-stg.mercadopago.com https://acs.mercadopago.com",
  "worker-src 'self' blob:",
  "media-src 'self' data: blob: https:",
  "manifest-src 'self'",
].join('; ')

const HTML_CONTENT_TYPE = /^(?:text\/html|application\/xhtml\+xml)(?:\s*;|$)/i
const META_TAG = /<meta\b[^>]*>/gi
const NONCE_PATTERN = /^[A-Za-z0-9+/_-]+={0,2}$/
const CONDITIONAL_CACHE_HEADERS = ['If-None-Match', 'If-Modified-Since']

function isHtmlResponse(response) {
  return HTML_CONTENT_TYPE.test(response.headers.get('Content-Type') || '')
}

function isDocumentRequest(request) {
  if (!request || !request.headers) return false
  const destination = request.headers.get('Sec-Fetch-Dest') || ''
  const accept = request.headers.get('Accept') || ''
  return destination === 'document'
    || accept.includes('text/html')
    || accept.includes('application/xhtml+xml')
}

// A conditional document request could make the asset server answer 304 and
// let the browser reuse a document with an older nonce. Ask for the full HTML
// instead, while leaving conditional caching for non-document assets intact.
function requestWithoutConditionalCacheHeaders(request) {
  if (!isDocumentRequest(request)) return null
  const headers = new Headers(request.headers)
  let changed = false
  for (const name of CONDITIONAL_CACHE_HEADERS) {
    if (!headers.has(name)) continue
    headers.delete(name)
    changed = true
  }
  return changed ? new Request(request, { headers }) : null
}

function escapeAttribute(value) {
  return String(value)
    .replaceAll('&', '&#38;')
    .replaceAll('"', '&#34;')
    .replaceAll('<', '&#60;')
    .replaceAll('>', '&#62;')
}

function isCspMeta(tag) {
  return /\bhttp-equiv\s*=\s*(["'])Content-Security-Policy\1/i.test(tag)
}

function isNonceMeta(tag) {
  return new RegExp(`\\bname\\s*=\\s*(["'])${CSP_NONCE_META_NAME}\\1`, 'i').test(tag)
}

function replaceMetaContent(tag, content) {
  const attribute = /\bcontent\s*=\s*(["'])(.*?)\1/i
  if (attribute.test(tag)) {
    return tag.replace(attribute, (_match, quote) => `content=${quote}${escapeAttribute(content)}${quote}`)
  }
  return tag.replace(/>$/, ` content="${escapeAttribute(content)}">`)
}

function insertIntoHead(html, markup) {
  if (/<\/head\s*>/i.test(html)) return html.replace(/<\/head\s*>/i, `${markup}\n$&`)
  return `${markup}\n${html}`
}

// Adds one nonce source to script-src and leaves every other directive and
// every existing script source untouched.
export function withCspNonce(policy, nonce) {
  if (!NONCE_PATTERN.test(String(nonce || ''))) throw new Error('Invalid CSP nonce')
  const nonceSource = `'nonce-${nonce}'`
  let foundScriptSource = false
  const declarations = String(policy || '')
    .split(';')
    .map((declaration) => declaration.trim())
    .filter(Boolean)
    .map((declaration) => {
      const [name, ...sources] = declaration.split(/\s+/)
      if (name.toLowerCase() !== 'script-src') return declaration
      foundScriptSource = true
      const withoutOldNonce = sources.filter((source) => !/^'nonce-.+'$/.test(source))
      return ['script-src', ...withoutOldNonce, nonceSource].join(' ')
    })

  if (!foundScriptSource) declarations.unshift(`script-src ${nonceSource}`)
  return declarations.join('; ')
}

// Generates 128 random bits and encodes them as a CSP base64-value.
export function createCspNonce() {
  const bytes = new Uint8Array(16)
  globalThis.crypto.getRandomValues(bytes)
  let binary = ''
  for (const byte of bytes) binary += String.fromCharCode(byte)
  return globalThis.btoa(binary)
}

// Replaces the static CSP meta with the response policy and exposes the exact
// nonce to the application through a dedicated, non-executable meta element.
export function injectCspNonce(html, policy, nonce) {
  const nonceMeta = `<meta name="${CSP_NONCE_META_NAME}" content="${escapeAttribute(nonce)}">`
  let foundCspMeta = false
  let insertedNonceMeta = false

  const updated = String(html || '').replace(META_TAG, (tag) => {
    if (isNonceMeta(tag)) return ''
    if (!isCspMeta(tag)) return tag
    foundCspMeta = true
    const cspMeta = replaceMetaContent(tag, policy)
    if (insertedNonceMeta) return cspMeta
    insertedNonceMeta = true
    return `${cspMeta}\n${nonceMeta}`
  })

  if (foundCspMeta) return updated
  const cspMeta = `<meta http-equiv="Content-Security-Policy" content="${escapeAttribute(policy)}">`
  return insertIntoHead(updated, `${cspMeta}\n${nonceMeta}`)
}

export async function onRequest(context) {
  const nextRequest = requestWithoutConditionalCacheHeaders(context.request)
  const response = await context.next(nextRequest || undefined)
  if (!isHtmlResponse(response)) return response

  const html = await response.text()
  const nonce = createCspNonce()
  const policy = withCspNonce(CANONICAL_CSP, nonce)
  const body = injectCspNonce(html, policy, nonce)
  const headers = new Headers(response.headers)

  headers.set('Content-Security-Policy', policy)
  // A nonce-bearing document must never be reused from an edge or browser cache.
  headers.set('Cache-Control', 'no-store, max-age=0')
  headers.delete('ETag')
  headers.delete('Last-Modified')
  headers.delete('Expires')
  // The Fetch API exposes a decoded body; do not label the replacement bytes
  // with the upstream transfer encoding.
  headers.delete('Content-Encoding')
  headers.set('Content-Length', String(new TextEncoder().encode(body).byteLength))

  return new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  })
}
